-- DB update 2026_09_10_01 -> 2026_09_10_02
-- Arcane Mage rework, Phase 1 (docs/arcane-mage-rework-design.md; see
-- .agents/skills/class-rework/SKILL.md for the phase breakdown).
--
-- New baseline spells (all in the 200000-209999 reserved block,
-- apps/dbc-tools/source/ids.yaml): 200067 Brilliance Aura, 200068 Arcane Ward, 200069 Mass
-- Invisibility, 200070 Time Warp. See each row's `notes` in
-- apps/dbc-tools/source/spells/mage.csv for its own design rationale.
--
-- Baseline-ified: Presence of Mind (12043) and Slow (31589) move from mage_talents.csv to
-- mage.csv ("Now baseline" in the design doc) - learn level 40 / 24 respectively. Arcane Blast
-- (30451) drops from learn level 64 to 10 ("Now learnable at level 10, will need to create
-- scaling for it") with a rebased placeholder damage curve (base_points 60, points_per_level
-- 15.4 - keeps the old level-84 total roughly intact at the new level-80 cap rather than
-- inventing numbers from scratch); flagged in Open Items as needing real tuning during the
-- Phase 4 playtest. Invisibility (66) moves learn level 68 -> 58 (user call, so it sits below
-- Mass Invisibility's 66) - not itself a rework spell, just an ordering fix alongside it.
--
-- Produced by `python3 apps/dbc-tools/generate.py` from apps/dbc-tools/source/{spells,talents}/*,
-- then hand-extracted to just the rows this phase owns - a full run also reproduces a large
-- pre-existing, unrelated spell_dbc diff (~399 spells across every class) and reserved-block
-- boilerplate for other DBCs; both excluded here, same discipline as the Frost Mage rework's
-- migrations (see data/sql/updates/db_world/2026_09_01_01.sql for precedent). The reserved-range
-- DELETE+INSERT (200000-209999) is kept in full, not trimmed - it's a contiguous-range replace,
-- so it must always carry every row in the range (including the Frost/Warrior rework's own
-- pre-existing 200001-200066 spells, unchanged) or those would be deleted without being
-- reinserted.
--
-- Regenerate/extend via: python3 apps/dbc-tools/generate.py (see apps/dbc-tools/README.md)

DELETE FROM `spell_dbc` WHERE `ID` BETWEEN 200000 AND 209999;
DELETE FROM `spell_dbc` WHERE `ID` IN (66, 30451, 12043, 31589);

DELETE FROM `talent_dbc` WHERE `ID` BETWEEN 60000 AND 60799;

DELETE FROM `talenttab_dbc` WHERE `ID` BETWEEN 60800 AND 60999;

DELETE FROM `skilllineability_dbc` WHERE `ID` BETWEEN 30400 AND 30499;

DELETE FROM `item_dbc` WHERE `ID` BETWEEN 70000 AND 79999;

DELETE FROM `spellcasttimes_dbc` WHERE `ID` BETWEEN 30000 AND 30099;

DELETE FROM `spellduration_dbc` WHERE `ID` BETWEEN 30100 AND 30199;

DELETE FROM `spellrange_dbc` WHERE `ID` BETWEEN 30200 AND 30299;

DELETE FROM `spellradius_dbc` WHERE `ID` BETWEEN 30300 AND 30399;

-- Trainer_spell (data/sql/base/'s copy is immutable per AGENTS.md - not part of dbc-tools'
-- pipeline, hand-authored). TrainerId 16 and 17 are both Mage trainers (`Requirement` = 8,
-- "Hello, mage!" greeting - see data/sql/base/db_world/trainer.sql). Pricing matched to the
-- existing curve at each level (data/sql/base/db_world/trainer_spell.sql: e.g. 20000/2000,
-- 40000/24000/4000, 52000/35000, 60000/42000 real-spell tiers).
--
-- Arcane Blast (30451): ReqLevel 64 -> 10, matching its mage.csv learn-level change; MoneyCost
-- 63000 (a level-64 price) rescaled down to the level-10 tier (400, matching Frostbolt/Fire
-- Blast's own cost at that level) - placeholder alongside its damage coefficient, same Open
-- Items tuning flag. 42894 (a later spell requiring 30451 as ReqAbility1) is untouched - it
-- still just requires owning Arcane Blast, regardless of what level that now happens at.
DELETE FROM `trainer_spell` WHERE (`TrainerId`, `SpellId`) IN ((16, 30451), (17, 30451));

-- Presence of Mind (12043) and Slow (31589): new rows, since neither had one before - both were
-- talent-granted, not trainer-taught, until this rework moved them to baseline.
DELETE FROM `trainer_spell` WHERE (`TrainerId`, `SpellId`) IN ((16, 12043), (17, 12043), (16, 31589), (17, 31589));

-- Invisibility (66): ReqLevel 68 -> 58 (user call), so it sits below Mass Invisibility's 66.
DELETE FROM `trainer_spell` WHERE (`TrainerId`, `SpellId`) IN ((16, 66), (17, 66));

-- New baseline spells (200067-200070).
DELETE FROM `trainer_spell` WHERE (`TrainerId`, `SpellId`) IN ((16, 200067), (16, 200068), (16, 200069), (16, 200070));

-- spell_script_names for the 3 new scripts (spell_mage.cpp): spell_mage_brilliance_aura,
-- spell_mage_mass_invisibility, spell_mage_time_warp.
DELETE FROM `spell_script_names` WHERE (`spell_id`, `ScriptName`) IN ((200067, 'spell_mage_brilliance_aura'), (200069, 'spell_mage_mass_invisibility'), (200070, 'spell_mage_time_warp'));
